import{_ as e,V as a,W as l,a0 as r}from"./framework-9a29aaa0.js";const s={},t=r('<ul><li><a href="#cs-6824%E7%AC%AC4%E8%AE%B2-vmware-ft">cs-6.824第4讲 vmware-FT</a><ul><li><a href="#%E5%A4%8D%E5%88%B6">复制</a></li></ul></li></ul><h1 id="cs-6-824第4讲-vmware-ft" tabindex="-1"><a class="header-anchor" href="#cs-6-824第4讲-vmware-ft" aria-hidden="true">#</a> cs-6.824第4讲 vmware-FT</h1><h2 id="复制" tabindex="-1"><a class="header-anchor" href="#复制" aria-hidden="true">#</a> 复制</h2><p>这节课会讨论更多关于容错和复制的问题，然后深入的看一下今天的论文，VMware FT。</p><p>那么复制可以解决什么样的问题呢，复制又在哪些方面存在它的局限性呢？</p><p>一、复制能解决的问题 复制可以处理单台计算机的 fail-stop 故障：Fail-stop 是容错领域的术语，指当出现故障时计算机单纯停止运行，而不是运算出错误结果。例如：</p><ul><li>例有人踢掉服务器电源线、拔掉服务器网线（即使服务器还在运行但从外界看与停止运行无异）。</li><li>还能处理一些硬件问题，如服务器风扇坏了导致 CPU 过热，CPU 自我关闭停止运行等情况。</li></ul><p>二、复制的局限性</p><ul><li>无法处理软件中的 bug。以 MapReduce 的 Master 节点为例，如果在 Master 程序中有一个 bug，即使复制并在两台计算机上运行，也会计算出相同的错误结果，其他组件会接受这个错误结果。不能通过复制软件（为软件构建多副本）来抵御软件的 bug。</li><li>无法处理硬件设计中的缺陷：当硬件有漏洞时会计算出错误的结果，此时基于复制技术无能为力。</li></ul><p>3：59</p>',10),i=[t];function c(n,o){return a(),l("div",null,i)}const u=e(s,[["render",c],["__file","lesson4.html.vue"]]);export{u as default};
